from pathlib import Path
from urllib.parse import urlparse
import os
from playwright.sync_api import sync_playwright,expect
ROOT=Path(__file__).resolve().parents[1]
with sync_playwright() as p:
 b=p.webkit.launch(executable_path=os.environ['PLAYWRIGHT_WEBKIT_EXECUTABLE']) if os.getenv('GIF_TEST_BROWSER')=='webkit' else p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox'])
 c=b.new_context(viewport={'width':390,'height':844})
 def route(r):
  u=urlparse(r.request.url);f=ROOT/u.path.lstrip('/')
  if f.is_dir():f/='index.html'
  if u.hostname=='edit.test' and f.is_file():r.fulfill(body=f.read_bytes(),content_type={'.js':'application/javascript','.css':'text/css','.json':'application/json'}.get(f.suffix,'text/html'))
  else:r.fulfill(status=404)
 c.route('**/*',route);page=c.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto('https://edit.test/');page.evaluate('TreinoStorage.ready');page.evaluate('localStorage.setItem("treinoAlunos",JSON.stringify([{nome:"Teste edição",student_id:"edit",treino:{A:["Glúteo Na Polia — 3×12 Cada Perna [Vídeo: https://youtu.be/KeepTEST123] [GIFs: https://drive.google.com/file/d/keepGIF/view]"]},titulos:{A:"A. Glúteos"}}]))');page.reload();page.evaluate('TreinoStorage.ready');row=page.locator('.sec-a ol>li').first;before=row.inner_text();page.locator('#workoutGifsBtn').click();main=page.locator('#workoutGifDialog');assert main.locator('.gif-card-actions button').nth(0).inner_text()=='Escolher outro vídeo';assert main.locator('.gif-card-actions button').nth(1).inner_text()=='✎ Editar';main.get_by_role('button',name='✎ Editar',exact=True).first.click();editor=page.get_by_role('dialog',name='Editar exercício na ficha');editor.get_by_role('textbox',name='Nome do exercício',exact=True).fill('Glúteo Na Polia Editado');editor.get_by_role('textbox',name='Prescrição',exact=True).fill('4×15 Cada Perna');editor.get_by_role('button',name='Salvar',exact=True).click();expect(editor).to_have_count(0);assert 'Glúteo Na Polia Editado' in row.inner_text() and '4×15 Cada Perna' in row.inner_text();assert main.locator('.gif-exercise-name').first.inner_text().endswith('Glúteo Na Polia Editado');raw=page.evaluate('JSON.parse(localStorage.getItem("treinoAlunos"))[0].treino.A[0]');assert 'KeepTEST123' in raw and 'keepGIF' in raw;card=main.locator('.gif-card').first;card.get_by_role('button',name='Escolher outro vídeo',exact=True).click();picker=page.locator('.gif-video-picker');a=picker.get_by_role('button',name='Adicionar vídeo',exact=True).bounding_box();z=picker.get_by_role('button',name='Editar biblioteca',exact=True).bounding_box();assert abs(a['y']-z['y'])<2 and a['x']<z['x'];picker.get_by_role('button',name='Limpar pesquisa',exact=True).click();choice=picker.locator('[data-video-id]').first;identifier=choice.get_attribute('data-video-id');picker.locator('.gif-preview-eye').first.click();preview=page.locator('#movementPreview');expect(preview.get_by_role('button',name='✓ Usar este vídeo',exact=True)).to_be_visible();assert preview.locator('.movement-controls>button').first.inner_text()=='✓ Usar este vídeo';preview.get_by_role('button',name='✓ Usar este vídeo',exact=True).click();expect(preview).not_to_be_visible();expect(picker).to_have_count(0);assert main.locator('.gif-card').first.get_attribute('data-video-id')==identifier;control=main.locator('.video-color-choice').first;assert control.locator('option[value=theme]').inner_text()=='Tema';assert control.evaluate('e=>Math.abs(e.getBoundingClientRect().y-e.querySelector("select").getBoundingClientRect().y)<8');assert not errors,errors;b.close();print('PASS: GIF edit persists name/dose/media to main; preview selection saves chosen video; compact inline theme control')
